mapper.select:
SELECT SV. ID, SVS.VEHICLE_ID, SS.NAME, SS.BADGE, SV.VEHICLE_PLATE, SS.PHONE, SS.DEP_NAME, SV.VEHICLE_TYPE, SV.IS_DELETE, SS.JCHE_NAME, SV.PARK_ID, SS.STATUS AS STAFF_STATUS, SV.CREATE_TIME FROM SMT_VEHICLE SV LEFT JOIN SMT_VEHICLE_STAFF SVS ON SV. ID = SVS.VEHICLE_ID LEFT JOIN SMT_STAFF SS ON SVS.STAFF_ID = SS. ID INNER JOIN SMT_VEHICLE_APPLY VA on SV.VEHICLE_PLATE=VA.VEHICLE_PLATE
SV.VEHICLE_ASCRIPTION = 0 and SV.IS_DELETE=0
and VA.AUTHORITY_ID=#{query.authorityId}
AND SS.NAME LIKE CONCAT(CONCAT('%',#{query.name}),'%')
AND SV.VEHICLE_PLATE LIKE CONCAT(CONCAT('%',#{query.vehiclePlate}),'%')
AND SV.VEHICLE_TYPE = #{query.vehicleType}
AND SS.DEP_ID = #{query.depId}
AND SS.COMP_ID = #{query.compId}
AND SS.STATUS = #{query.staffStatus}
AND SS.JCHE_NAME = #{query.welfareLevel}
AND SV.IS_DELETE = #{query.isDelete}
AND instr(','||SV.PARK_ID||',', ',' || #{query.parkId} || ',') <> 0
instr(','||SV.PARK_ID||',', ',' || #{tempId} || ',') <> 0
ORDER BY SV.CREATE_TIME DESC

SELECT SV. ID, SVS.VEHICLE_ID, SS.NAME, SS.BADGE, SV.VEHICLE_PLATE, SS.PHONE, SS.DEP_NAME, SV.VEHICLE_TYPE, SV.IS_DELETE, SS.JCHE_NAME, SS.STATUS AS STAFF_STATUS, SV.PARK_ID, SV.CREATE_TIME FROM SMT_VEHICLE SV LEFT JOIN SMT_VEHICLE_STAFF SVS ON SV. ID = SVS.VEHICLE_ID LEFT JOIN SMT_STAFF SS ON SVS.STAFF_ID = SS. ID RIGHT JOIN ( SELECT DISTINCT SVA.VEHICLE_ID FROM SMT_VEHICLE_APPLY SVA
AND SVA.STATUS = #{query.status}
AND SVA.AUTHORITY_ID = #{query.authorityId}
) SVA ON SVA.VEHICLE_ID = SV. ID
SV.VEHICLE_ASCRIPTION = 1 and SV.IS_DELETE=0
AND SS.NAME LIKE CONCAT(CONCAT('%',#{query.name}),'%')
AND SV.VEHICLE_PLATE LIKE CONCAT(CONCAT('%',#{query.vehiclePlate}),'%')
AND SV.VEHICLE_TYPE = #{query.vehicleType}
AND SS.DEP_ID = #{query.depId}
AND SS.COMP_ID = #{query.compId}
AND SS.STATUS = #{query.staffStatus}
AND SS.JCHE_NAME = #{query.welfareLevel}
AND SV.IS_DELETE = #{query.isDelete}
AND instr(','||SV.PARK_ID||',', ',' || #{query.parkId} || ',') <> 0
instr(','||SV.PARK_ID||',', ',' || #{tempId} || ',') <> 0
ORDER BY SV.CREATE_TIME DESC

SELECT SV.ID, SNS.NAME, SNS.PHONE, SNS.REMARK, VA.PARK_ID, SV.VEHICLE_PLATE, SV.VEHICLE_BRAND, SV.VEHICLE_COLOR, SV.VEHICLE_TYPE, SV.DRIVER_LICENSE_ID, SV.DRIVINGL_LICENSE_ID, VA.AUTHORITY_ID, SV.CREATE_TIME FROM SMT_NOT_STAFF SNS LEFT JOIN SMT_VEHICLE SV ON SV.ID = SNS.VEHICLE_ID LEFT JOIN SMT_VEHICLE_APPLY VA ON SV.ID = VA.VEHICLE_ID
AND SV.IS_DELETE = #{query.isDelete}
AND SV.VEHICLE_PLATE LIKE CONCAT(CONCAT('%',#{query.vehiclePlate}),'%')
AND SV.VEHICLE_ASCRIPTION = #{query.vehicleAscription}
AND VA.AUTHORITY_ID = #{query.authorityId}
AND instr(','||SNS.PARK_ID||',', ',' || #{query.parkId} || ',') <> 0
instr(','||SNS.PARK_ID||',', ',' || #{tempId} || ',') <> 0
AND SV.ID = #{query.id}
ORDER BY SV.CREATE_TIME DESC

mapper.update:
                UPDATE SMT_VEHICLE SV
				SET SV.IS_DELETE = #{status}
				WHERE
				    SV."ID" =#{id}

mapper.select:
SELECT ( SELECT "COUNT" (DISTINCT SSV.VEHICLE_PLATE) FROM SMT_SNAP_VEHICLE SSV WHERE ( SSV.VEHICLE_ASCRIPTION = 1 OR SSV.VEHICLE_ASCRIPTION = 2 )
and SSV.PARK_ID in
#{item}
) AS INNER_TOTAL, ( SELECT "COUNT" (DISTINCT SSV.VEHICLE_PLATE) FROM SMT_SNAP_VEHICLE SSV WHERE ( SSV.VEHICLE_ASCRIPTION = 3 OR SSV.VEHICLE_ASCRIPTION = 4 )
and SSV.PARK_ID in
#{item}
) AS FOREIGN_TOTAL FROM dual

SELECT SP.ID, SP.PARK_NAME FROM SMT_PARK_BU SPB INNER JOIN SMT_PARK SP ON SP.ID = SPB.PARK_ID
AND SPB.COMP_ID = #{compId}
AND SPB.PARK_ID IN
#{tempId}

SELECT SP.ID, SP.PARK_NAME FROM SMT_PARK SP, SMT_ORGANIZE_RELATION SOR WHERE SP.ID=SOR.PARK_ID
AND SOR.ID = #{compId}
AND SOR.PARK_ID IN
#{tempId}
